with d as (select $1::jsonb as j), ins as (insert into serena_mensagens (contato_id,papel,texto,canal,autor,criado_em) select (e->>'c')::uuid, e->>'p', e->>'t', e->>'ca', nullif(e->>'au',''), to_timestamp((e->>'ts')::double precision) from d, jsonb_array_elements(coalesce(j->'msgs','[]'::jsonb)) e returning id), pw as (insert into serena_wpp_pausas (telefone, ate, motivo) select d.j->>'telefone', now() + make_interval(mins => coalesce((d.j->>'pausa_min')::int, 720)), coalesce(nullif(d.j->>'motivo_handoff',''), 'handoff') from d where (d.j->>'handoff')::boolean is true and d.j->>'canal' = 'whatsapp' and nullif(d.j->>'telefone','') is not null on conflict (telefone) do update set ate = excluded.ate, motivo = excluded.motivo, atualizado_em = now() returning 1), pc as (update serena_conversas v set ia_pausada = true from d where (d.j->>'handoff')::boolean is true and d.j->>'canal' <> 'whatsapp' and v.id = (select x.id from serena_conversas x where x.contato_id = (d.j->>'contato_id')::uuid order by x.aberta_em desc limit 1) returning 1), pc2 as (insert into serena_conversas (contato_id, canal, ia_pausada) select (d.j->>'contato_id')::uuid, d.j->>'canal', true from d where (d.j->>'handoff')::boolean is true and d.j->>'canal' <> 'whatsapp' and nullif(d.j->>'contato_id','') is not null and not exists (select 1 from serena_conversas x where x.contato_id = (d.j->>'contato_id')::uuid) returning 1), at as (insert into serena_atribuicoes (contato_id, status, motivo) select (d.j->>'contato_id')::uuid, 'aberto', coalesce(nullif(d.j->>'motivo_handoff',''), 'handoff') from d where (d.j->>'handoff')::boolean is true and nullif(d.j->>'contato_id','') is not null on conflict (contato_id) do update set status = 'aberto', motivo = excluded.motivo, atualizado_em = now() returning 1), lc as (insert into serena_lacunas (contato_id, canal, pergunta, resposta_serena, tema) select (d.j->>'contato_id')::uuid, d.j->>'canal', d.j->'lacuna'->>'pergunta', d.j->'lacuna'->>'resposta', d.j->'lacuna'->>'tema' from d where jsonb_typeof(d.j->'lacuna') = 'object' and nullif(d.j->'lacuna'->>'pergunta','') is not null and nullif(d.j->>'contato_id','') is not null and not exists (select 1 from serena_lacunas l where l.contato_id = (d.j->>'contato_id')::uuid and l.criado_em > now() - interval '2 hours') returning 1), tg as (insert into serena_etiquetas (contato_id, etiqueta, origem) select (d.j->>'contato_id')::uuid, t, 'auto' from d, jsonb_array_elements_text(coalesce(d.j->'tags','[]'::jsonb)) t where nullif(d.j->>'contato_id','') is not null on conflict do nothing returning 1) select (select count(*) from ins)::int as gravadas, (select count(*) from pw)::int as pausa_wpp, ((select count(*) from pc) + (select count(*) from pc2))::int as pausa_site, (select count(*) from at)::int as fila, (select count(*) from tg)::int as etiquetas, (select count(*) from lc)::int as lacunas
